"""Schema-based record validation."""

import re
import logging
from typing import Any, Callable, Dict, List, Tuple, Union

logger = logging.getLogger(__name__)


# Type checkers for schema validation
TYPE_CHECKERS: Dict[str, Callable[[Any], bool]] = {
    "string": lambda v: isinstance(v, str),
    "int": lambda v: isinstance(v, int) and not isinstance(v, bool),
    "float": lambda v: isinstance(v, (int, float)) and not isinstance(v, bool),
    "bool": lambda v: isinstance(v, bool),
    "list": lambda v: isinstance(v, list),
    "dict": lambda v: isinstance(v, dict),
}


def validate(
    record_data: Dict[str, Any], schema: Dict[str, Dict[str, Any]]
) -> Tuple[bool, List[str]]:
    """Validate a record against a schema definition.

    Schema is a dict of field_name -> rules, where rules can contain:
      - required: bool
      - type: str (one of TYPE_CHECKERS keys)
      - min_length / max_length: int (for strings)
      - min_value / max_value: numeric (for numbers)
      - pattern: str (regex for strings)
      - choices: list of allowed values
      - custom: callable returning (bool, str)
    """
    errors: List[str] = []

    for field_name, rules in schema.items():
        value = record_data.get(field_name)

        # Required check
        if rules.get("required") and (value is None or value == ""):
            errors.append(f"Field '{field_name}' is required")
            continue

        # Skip optional fields that are absent
        if value is None:
            continue

        # Type check
        expected_type: Optional[str] = rules.get("type")
        if expected_type:
            checker = TYPE_CHECKERS.get(expected_type)
            if checker and not checker(value):
                errors.append(
                    f"Field '{field_name}' expected type {expected_type}, got {type(value).__name__}"
                )
                continue

        # String validations
        if isinstance(value, str):
            min_len: Optional[int] = rules.get("min_length")
            if min_len is not None and len(value) < min_len:
                errors.append(
                    f"Field '{field_name}' must be at least {min_len} characters"
                )

            max_len: Optional[int] = rules.get("max_length")
            if max_len is not None and len(value) > max_len:
                errors.append(
                    f"Field '{field_name}' must be at most {max_len} characters"
                )

            pattern: Optional[str] = rules.get("pattern")
            if pattern and not re.match(pattern, value):
                errors.append(f"Field '{field_name}' does not match pattern {pattern}")

        # Numeric validations
        if isinstance(value, (int, float)) and not isinstance(value, bool):
            min_val: Optional[Union[int, float]] = rules.get("min_value")
            if min_val is not None and value < min_val:
                errors.append(
                    f"Field '{field_name}' must be >= {min_val}"
                )

            max_val: Optional[Union[int, float]] = rules.get("max_value")
            if max_val is not None and value > max_val:
                errors.append(
                    f"Field '{field_name}' must be <= {max_val}"
                )

        # Choices
        choices: Optional[List[Any]] = rules.get("choices")
        if choices and value not in choices:
            errors.append(f"Field '{field_name}' must be one of {choices}")

        # Custom validator
        custom: Optional[Callable[[Any], Tuple[bool, str]]] = rules.get("custom")
        if custom and callable(custom):
            is_valid, msg = custom(value)
            if not is_valid:
                errors.append(f"Field '{field_name}': {msg}")

    return len(errors) == 0, errors


def validate_batch(
    records_data: List[Dict[str, Any]], schema: Dict[str, Dict[str, Any]]
) -> List[Dict[str, Any]]:
    """Validate a list of records, returning per-record results."""
    results: List[Dict[str, Any]] = []
    for i, record_data in enumerate(records_data):
        is_valid, errors = validate(record_data, schema)
        results.append({"index": i, "valid": is_valid, "errors": errors})
    return results


def build_schema(field_definitions: List[Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
    """Build a schema dict from a simplified list of field definitions.

    Each definition is a dict with 'name', 'type', and optional constraint keys.
    """
    schema: Dict[str, Dict[str, Any]] = {}
    for defn in field_definitions:
        name: str = defn.pop("name")
        schema[name] = defn
    return schema


# Common email validation
